{
  "name": "create_ticket",
  "description": "Create a new support ticket in a specified queue",
  "inputSchema": {
    "type": "object",
    "properties": {
      "subject": { "type": "string", "maxLength": 200 },
      "description": { "type": "string", "maxLength": 5000 },
      "priority": { "type": "string", "enum": ["low", "normal", "high", "urgent"] },
      "queue": { "type": "string", "enum": ["billing", "technical", "account"] }
    },
    "required": ["subject", "description", "queue"]
  }
}

{
  "name": "add_comment",
  "description": "Add an internal or customer facing comment to an existing ticket",
  "inputSchema": {
    "type": "object",
    "properties": {
      "ticketId": { "type": "string" },
      "body": { "type": "string", "maxLength": 4000 },
      "visibility": { "type": "string", "enum": ["internal", "customer"] }
    },
    "required": ["ticketId", "body", "visibility"]
  }
}
